#!/usr/bin/env bash
# Generated by MiniMax M3.1 Flash without human creative authorship.
# SPDX-License-Identifier: LGPL-2.0-or-later
#
# Build the ARM64X forwarder DLL (PIMETextService.dll) on Windows.
#
# Upstream builds this with MSVC's link.exe:
#
#   link /nologo /dll /noentry /nodefaultlib /machine:arm64x
#        /defArm64Native:PIMETextService_arm64x_arm64.def
#        /def:PIMETextService_arm64x_x64.def
#        /out:PIMETextService.dll
#
# link.exe synthesises the ARM64X metadata (dual export tables, the CHPE
# metadata block, the .a64xrm redirection table and the ARM64X dynamic
# relocations) itself. lld-link has no such synthesis: it can only carry
# ARM64X metadata that already exists in the input objects, and given
# nothing but /def files it writes no output at all.
#
# So this script feeds lld-link the two metadata objects the ARM64X layout
# needs - a native ARM64 load configuration and an ARM64EC one that also
# carries the CHPE metadata block - and lets lld-link do the rest. The
# resulting image is a pure forwarder: it has no code of its own, only the
# two export tables, and the Windows loader routes native ARM64 processes to
# the ARM64 backend and emulated x64 processes to the x64 backend.
#
# Usage: build-forwarder.sh <arm64.def> <x64.def> <out.dll>
set -euo pipefail
export MSYS_NO_PATHCONV=1

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
TOOLS="$ROOT/.tools"
CC="$TOOLS/mingw64/bin/clang-cl.exe"
LL="$TOOLS/mingw64/bin/lld-link.exe"
OBJDIR="$TOOLS/arm64x"

ARM_DEF="$(cygpath -w "$1")"
X64_DEF="$(cygpath -w "$2")"
OUT="$(cygpath -w "$3")"
mkdir -p "$OBJDIR"

asm() { # asm <target> <src.s> <out.obj>
  "$CC" --target="$1" -c "-Fo$3" "$2" 2>&1 | grep -E ": (error|fatal error):" || true
}

asm aarch64-pc-windows-msvc "$(cygpath -w "$HERE/loadconfig-native.s")" \
    "$(cygpath -w "$OBJDIR/lc-native.obj")"
asm arm64ec-pc-windows-msvc "$(cygpath -w "$HERE/loadconfig-ec.s")" \
    "$(cygpath -w "$OBJDIR/lc-ec.obj")"

"$LL" -nologo -dll -noentry -nodefaultlib -machine:arm64x \
  "-defArm64Native:$ARM_DEF" "-def:$X64_DEF" "-out:$OUT" \
  "$(cygpath -w "$OBJDIR/lc-native.obj")" "$(cygpath -w "$OBJDIR/lc-ec.obj")"

echo "ARM64X forwarder: $3"
